package dev.zakocoder.app.projects

/** Small, original Flutter scaffold. Platform files are generated by the installed Flutter SDK. */
internal object FlutterProjectTemplates {
    private val reserved = setOf(
        "abstract", "as", "assert", "async", "await", "base", "break", "case", "catch", "class",
        "const", "continue", "covariant", "default", "deferred", "do", "dynamic", "else", "enum",
        "export", "extends", "extension", "external", "factory", "false", "final", "finally", "for",
        "Function", "get", "hide", "if", "implements", "import", "in", "inout", "interface", "is", "late",
        "library", "mixin", "native", "new", "null", "of", "on", "operator", "part", "required", "rethrow",
        "return", "out", "patch", "sealed", "set", "show", "source", "static", "super", "switch", "sync", "this", "throw",
        "true", "try", "type", "typedef", "var", "void", "when", "while", "with", "yield",
        "flutter", "flutter_test", "flutter_lints", "collection", "meta", "test", "dart",
    ).map(String::lowercase).toSet()

    fun packageName(projectName: String): String {
        val cleaned = ProjectTemplates.identifier(projectName).replace('-', '_')
        return if (cleaned.first().isDigit() || cleaned in reserved) "app_$cleaned" else cleaned
    }

    fun files(projectName: String): Map<String, String> {
        val name = packageName(projectName)
        return linkedMapOf(
            "pubspec.yaml" to """
                name: $name
                description: A Flutter application created with ZakoCoder.
                publish_to: 'none'
                version: 1.0.0+1
                environment:
                  sdk: '>=3.3.0 <4.0.0'
                dependencies:
                  flutter:
                    sdk: flutter
                dev_dependencies:
                  flutter_test:
                    sdk: flutter
                flutter:
                  uses-material-design: true
            """.trimIndent() + "\n",
            "analysis_options.yaml" to "analyzer:\n  language:\n    strict-casts: true\nlinter:\n  rules:\n    avoid_print: true\n",
            "lib/main.dart" to MAIN,
            "test/widget_test.dart" to """
                import 'package:flutter/material.dart';
                import 'package:flutter_test/flutter_test.dart';
                import 'package:$name/main.dart';

                void main() {
                  testWidgets('counter increments after a tap', (tester) async {
                    await tester.pumpWidget(const ZakoApp());
                    expect(find.text('Count: 0'), findsOneWidget);
                    await tester.tap(find.byIcon(Icons.add));
                    await tester.pump();
                    expect(find.text('Count: 1'), findsOneWidget);
                  });
                }
            """.trimIndent() + "\n",
            ".gitignore" to ".dart_tool/\n.packages\n.flutter-plugins\n.flutter-plugins-dependencies\n/build/\n/android/local.properties\n/android/.gradle/\n/android/key.properties\n*.jks\n*.keystore\n",
            "README.md" to """
                # Flutter application

                由 ZakoCoder 创建的 Flutter 项目，Dart 包名为 `$name`。
                在应用私有工作区开发；共享存储不支持工具链需要的全部文件权限和符号链接。

                ## 初始化

                在环境页安装 Flutter 工具包，然后在本项目终端执行：

                ```sh
                flutter create --platforms=android,web --project-name $name .
                flutter pub get
                flutter analyze
                flutter test
                ```

                初始化命令补齐 Android/Web 平台文件，默认保留已有源码与测试。
                请勿添加 `--overwrite`；已有项目请先备份并检查差异。
                首次安装和依赖获取需要联网，可能下载较多资源。

                ## 浏览器预览

                ```sh
                flutter run -d web-server --web-hostname 127.0.0.1 --web-port 8080
                ```

                等服务就绪后，使用终端的网页预览入口打开 8080 端口。
                Web server 不提供完整 Chrome 调试能力；修改后按终端提示刷新或重启。

                ## Android Debug APK

                先安装 Android 和 NDK 工具包，再执行：

                ```sh
                flutter build apk --debug --target-platform android-arm64
                ```

                产物：`build/app/outputs/flutter-apk/app-debug.apk`。
                可从项目文件列表打开 APK 并安装。插件若依赖额外原生组件，需要相应工具链；
                本模板不承诺任意插件、iOS 或桌面平台构建。
            """.trimIndent() + "\n",
        )
    }

    private val MAIN = """
        import 'package:flutter/material.dart';

        void main() => runApp(const ZakoApp());

        class ZakoApp extends StatelessWidget {
          const ZakoApp({super.key});

          @override
          Widget build(BuildContext context) => MaterialApp(
                title: 'Flutter project',
                theme: ThemeData(colorSchemeSeed: Colors.blue, useMaterial3: true),
                home: const CounterPage(),
              );
        }

        class CounterPage extends StatefulWidget {
          const CounterPage({super.key});

          @override
          State<CounterPage> createState() => _CounterPageState();
        }

        class _CounterPageState extends State<CounterPage> {
          int count = 0;

          @override
          Widget build(BuildContext context) => Scaffold(
                appBar: AppBar(title: const Text('Flutter project')),
                body: Center(child: Text('Count: ${'$'}count')),
                floatingActionButton: FloatingActionButton(
                  onPressed: () => setState(() => count++),
                  tooltip: 'Increment',
                  child: const Icon(Icons.add),
                ),
              );
        }
    """.trimIndent() + "\n"
}
